1	// pattern: Imperative Shell
2	//
3	// The RPC layer: one function from (caller node id, request) to response. It owns the
4	// cross-table sequences the `db/` submodules deliberately don't — redeeming an enrollment
5	// code and recording the enrollment in one transaction — and the authorization order that
6	// every RPC shares: enrollment first, then the rate-limit charge, then the work.
7	//
8	// Charging *after* the enrollment check is deliberate: an unenrolled node's requests are
9	// rejected on a cheap read, so it can never spend an enrolled node's budget, and a node
10	// that has not yet enrolled cannot exhaust a bucket keyed to an identity it hasn't earned.
11	
12	use std::sync::Arc;
13	
14	use sqlx::SqlitePool;
15	
16	use crate::config::Config;
17	use crate::db;
18	use crate::protocol::{PushOutcome, Request, Response};
19	use crate::rate_limit::{Bucket, RateLimiter};
20	
21	/// Everything an RPC needs: the store, the operator's policy, and the limiter.
22	pub struct RelayService {
23	    pub db: SqlitePool,
24	    pub config: Arc<Config>,
25	    pub limits: RateLimiter,
26	}
27	
28	/// Bytes of randomness behind a push handle. 128 bits: unguessable, and short enough that
29	/// a padded APNs payload doesn't pay for it.
30	const HANDLE_BYTES: usize = 16;
31	
32	impl RelayService {
33	    pub fn new(db: SqlitePool, config: Arc<Config>) -> Self {
34	        let limits = RateLimiter::new(config.rate_limits.clone());
35	        Self { db, config, limits }
36	    }
37	
38	    /// Dispatch one request from `node_id` (the QUIC peer's verified identity).
39	    pub async fn handle(&self, node_id: &str, request: Request) -> Response {
40	        match request {
41	            Request::Enroll { claim_code } => self.enroll(node_id, claim_code.as_deref()).await,
42	            Request::RegisterHandle {
43	                apns_token,
44	                apns_topic,
45	            } => {
46	                self.register_handle(node_id, &apns_token, &apns_topic)
47	                    .await
48	            }
49	            Request::DropHandle { handle } => self.drop_handle(node_id, &handle).await,
50	            Request::Push { handle, .. } => self.push(node_id, &handle).await,
51	        }
52	    }
53	
54	    async fn enroll(&self, node_id: &str, claim_code: Option<&str>) -> Response {
55	        if !self.limits.check(node_id, Bucket::Registration) {
56	            return Response::Throttled;
57	        }
58	
59	        if self.config.open_enrollment {
60	            return match db::enrollments::insert_enrollment(&self.db, node_id, None).await {
61	                // Idempotent whether or not a row was created: an open relay charges
62	                // nothing, so a repeat costs the caller nothing to report as success.
63	                Ok(_) => Response::Ok,
64	                Err(e) => internal(e, "failed to record enrollment"),
65	            };
66	        }
67	
68	        // Everything below runs inside one transaction, enrollment probe included. Reading
69	        // "already enrolled?" outside it would let two concurrent enrolls both see `false`,
70	        // and the one that lost the insert would have spent its grant code for nothing.
71	        let mut tx = match self.db.begin().await {
72	            Ok(tx) => tx,
73	            Err(e) => return internal(e, "failed to open enrollment transaction"),
74	        };
75	        match db::enrollments::is_enrolled(&mut *tx, node_id).await {
76	            // Idempotent: a node re-enrolling after a restart is not charged a code again.
77	            // Dropping `tx` unread rolls back, so nothing was consumed.
78	            Ok(true) => return Response::Ok,
79	            Ok(false) => {}
80	            Err(e) => return internal(e, "failed to check enrollment"),
81	        }
82	
83	        let Some(code) = claim_code else {
84	            // Same shape as a bad code: a caller cannot use the response to learn whether
85	            // this relay runs open enrollment beyond what its operator published.
86	            return Response::Denied;
87	        };
88	
89	        match db::enrollment_codes::consume_code(&mut *tx, code, node_id).await {
90	            Ok(true) => {}
91	            Ok(false) => return Response::Denied,
92	            Err(e) => return internal(e, "failed to redeem enrollment code"),
93	        }
94	        match db::enrollments::insert_enrollment(&mut *tx, node_id, Some(code)).await {
95	            Ok(true) => {}
96	            // The row already existed despite the probe above — only reachable if another
97	            // writer slipped in. Abandon the transaction (rollback), which un-redeems the
98	            // code, and report the enrollment that already stands.
99	            Ok(false) => return Response::Ok,
100	            Err(e) => return internal(e, "failed to record enrollment"),
101	        }
102	        match tx.commit().await {
103	            Ok(()) => {
104	                tracing::info!(%node_id, "node enrolled with a grant code");
105	                Response::Ok
106	            }
107	            Err(e) => internal(e, "failed to commit enrollment"),
108	        }
109	    }
110	
111	    async fn register_handle(&self, node_id: &str, apns_token: &str, apns_topic: &str) -> Response {
112	        match self.require_enrolled(node_id, Bucket::Registration).await {
113	            Ok(()) => {}
114	            Err(response) => return response,
115	        }
116	
117	        if apns_token.is_empty() || apns_topic.is_empty() {
118	            return Response::BadRequest {
119	                reason: "apnsToken and apnsTopic are required".into(),
120	            };
121	        }
122	        // An empty served-topic list means "any topic" — the self-run posture, where the
123	        // operator owns every app that could register. A non-empty list is an allowlist.
124	        if !self.config.apns.topics.is_empty()
125	            && !self
126	                .config
127	                .apns
128	                .topics
129	                .iter()
130	                .any(|topic| topic == apns_topic)
131	        {
132	            return Response::BadRequest {
133	                reason: "this relay does not serve that apnsTopic".into(),
134	            };
135	        }
136	
137	        let handle = generate_handle();
138	        match db::handles::register_handle(&self.db, node_id, apns_token, apns_topic, &handle).await
139	        {
140	            Ok(handle) => Response::Handle { handle },
141	            Err(e) => internal(e, "failed to register handle"),
142	        }
143	    }
144	
145	    async fn drop_handle(&self, node_id: &str, handle: &str) -> Response {
146	        match self.require_enrolled(node_id, Bucket::Registration).await {
147	            Ok(()) => {}
148	            Err(response) => return response,
149	        }
150	        // Idempotent, and silent about ownership: dropping a handle that belongs to
151	        // another node is the same 'ok' as dropping one that never existed.
152	        match db::handles::drop_handle(&self.db, node_id, handle).await {
153	            Ok(_) => Response::Ok,
154	            Err(e) => internal(e, "failed to drop handle"),
155	        }
156	    }
157	
158	    async fn push(&self, node_id: &str, handle: &str) -> Response {
159	        match db::enrollments::is_enrolled(&self.db, node_id).await {
160	            Ok(true) => {}
161	            Ok(false) => {
162	                return Response::Pushed {
163	                    outcome: PushOutcome::NotEnrolled,
164	                }
165	            }
166	            Err(e) => return internal(e, "failed to check enrollment"),
167	        }
168	        if !self.limits.check(node_id, Bucket::Push) {
169	            return Response::Pushed {
170	                outcome: PushOutcome::Throttled,
171	            };
172	        }
173	
174	        match db::handles::resolve_handle(&self.db, node_id, handle).await {
175	            Ok(Some(_)) => Response::Pushed {
176	                // The APNs pipeline lands in the next phase; until then a well-formed push
177	                // to a real handle is honestly reported as an upstream failure rather than
178	                // as a delivery that never happened.
179	                outcome: PushOutcome::ApnsError,
180	            },
181	            Ok(None) => Response::Pushed {
182	                outcome: PushOutcome::UnknownHandle,
183	            },
184	            Err(e) => internal(e, "failed to resolve handle"),
185	        }
186	    }
187	
188	    /// The shared gate for every RPC but `enroll`: enrolled first, then charged.
189	    async fn require_enrolled(&self, node_id: &str, bucket: Bucket) -> Result<(), Response> {
190	        match db::enrollments::is_enrolled(&self.db, node_id).await {
191	            Ok(true) => {}
192	            Ok(false) => return Err(Response::NotEnrolled),
193	            Err(e) => return Err(internal(e, "failed to check enrollment")),
194	        }
195	        if !self.limits.check(node_id, bucket) {
196	            return Err(Response::Throttled);
197	        }
198	        Ok(())
199	    }
200	}
