        let tokens: std::collections::HashSet<&str> = requests
            .iter()
            .map(|r| r.headers["authorization"].to_str().expect("ascii"))
            .collect();
        assert_eq!(
            tokens.len(),
            1,
            "three pushes inside the token window must share one provider token"
        );
    }
