48	/// Convert a config `database_url` (a plain path or a sqlx URL) into a sqlx URL.
49	fn to_sqlite_url(s: &str) -> String {
50	    if s.starts_with("sqlite:") {
51	        s.to_owned()
52	    } else if s.starts_with('/') {
53	        format!("sqlite://{s}")
54	    } else {
