59	/// Parse a `<number><s|m|h|d>` duration into seconds (Functional Core). A bare number is
60	/// read as seconds.
61	fn parse_ttl(spec: &str) -> anyhow::Result<i64> {
62	    let spec = spec.trim();
63	    let (digits, multiplier) = match spec.chars().last() {
64	        Some('s') => (&spec[..spec.len() - 1], 1),
65	        Some('m') => (&spec[..spec.len() - 1], 60),
66	        Some('h') => (&spec[..spec.len() - 1], 3600),
67	        Some('d') => (&spec[..spec.len() - 1], 86_400),
68	        _ => (spec, 1),
69	    };
70	    let value: i64 = digits
71	        .parse()
72	        .with_context(|| format!("invalid --ttl {spec:?}: expected e.g. 60m, 24h, 7d, 900s"))?;
73	    if value <= 0 {
74	        anyhow::bail!("--ttl must be positive");
75	    }
76	    value
77	        .checked_mul(multiplier)
78	        .context("--ttl is implausibly large")
79	}
