81	/// A code an operator can read aloud: 120 bits of entropy as 24 base32 characters, in
82	/// four groups of six for transcription.
83	fn generate_enrollment_code() -> String {
84	    let mut bytes = [0u8; 15];
85	    rand_core::RngCore::fill_bytes(&mut rand_core::OsRng, &mut bytes);
86	    let encoded = data_encoding::BASE32_NOPAD.encode(&bytes);
87	    encoded
88	        .as_bytes()
89	        .chunks(6)
90	        .map(|chunk| String::from_utf8_lossy(chunk).into_owned())
91	        .collect::<Vec<_>>()
92	        .join("-")
93	}
