99	        // env-only config would run the relay under settings the operator never chose.
100	        Some(path) => config::load_with_env(&path, &env)
101	            .with_context(|| format!("failed to load config from {}", path.display())),
102	        None => {
103	            let default_path = PathBuf::from("notify-relay.toml");
104	            match config::load_with_env(&default_path, &env) {
105	                Ok(config) => Ok(config),
