145	    // Before binding anything: a configured-but-unreadable APNs key is a hard startup
146	    // failure, not a warning. A relay that came up looking healthy and then answered
147	    // `apnsError` to every push would be far harder to diagnose than a refusal to start.
148	    let apns = apns::ApnsClient::new(&config.apns).context("failed to load APNs credentials")?;
